+using System.ComponentModel;
+using Microsoft.Extensions.AI;
+
+namespace ResearchAgent.Tools;
+
+public sealed class WebSearchTool
+{
+    private static readonly HttpClient HttpClient = new();
+
+    [Description("Searches the web for information on a given query. Returns a summary of search results.")]
+    public static async Task<string> SearchWebAsync(
+        [Description("The search query to look up on the web")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        Console.WriteLine($"  [WebSearch] Searching for: \"{query}\"");
+
+        try
+        {
+            // Use DuckDuckGo instant answer API for web search
+            var encoded = Uri.EscapeDataString(query);
+            var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";
+
+            var response = await HttpClient.GetStringAsync(url, cancellationToken);
+            var doc = System.Text.Json.JsonDocument.Parse(response);
+            var root = doc.RootElement;
+
+            var results = new List<string>();
+
+            var abstractText = root.GetProperty("AbstractText").GetString();
+            if (!string.IsNullOrWhiteSpace(abstractText))
+            {
+                var source = root.GetProperty("AbstractSource").GetString();
+                results.Add($"[{source}] {abstractText}");
+            }
+
+            if (root.TryGetProperty("RelatedTopics", out var topics))
+            {
+                foreach (var topic in topics.EnumerateArray().Take(5))
+                {
+                    if (topic.TryGetProperty("Text", out var text))
+                    {
+                        var topicText = text.GetString();
+                        if (!string.IsNullOrWhiteSpace(topicText))
+                        {
+                            results.Add(topicText);
+                        }
+                    }
+                }
+            }
+
+            if (results.Count == 0)
+            {
+                return $"No detailed results found for '{query}'. Try rephrasing the query or breaking it into smaller searches.";
+            }
+
+            return string.Join("\n\n", results);
+        }
+        catch (Exception ex)
+        {
+            return $"Search failed: {ex.Message}. Try a different query.";
+        }
+    }
+}
+

