using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTakingTool
{
    private readonly List<(string Topic, string Content)> _notes = [];

    [Description("Saves a research note with a topic label and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short topic label for the note")] string topic,
        [Description("The content of the note to save")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  [Notes] Saved note on: \"{topic}\"");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes to help compile the final summary.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes saved yet.";
        }

        var formatted = _notes.Select((n, i) => $"[{i + 1}] {n.Topic}: {n.Content}");
        Console.WriteLine($"  [Notes] Retrieved {_notes.Count} note(s)");
        return string.Join("\n\n", formatted);
    }
}

