using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using OpenAI;
using ResearchAgent.Tools;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "OPENAI_API_KEY environment variable is not set. Set it to your OpenAI API key.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Register the chat client with function invocation support
builder.Services.AddChatClient(sp =>
{
    var openAiClient = new OpenAIClient(apiKey);
    var chatClient = openAiClient.GetChatClient(modelId);
    IChatClient meaiClient = new OpenAIChatClient(chatClient);

    return new ChatClientBuilder(meaiClient)
        .UseFunctionInvocation()
        .Build();
});

var host = builder.Build();

// Create tools
var noteTool = new NoteTakingTool();
var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetAllNotes),
};

// Get the chat client from DI
var chatClient = host.Services.GetRequiredService<IChatClient>();

// Create the agent with tool access
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic to research:
        1. Search the web for relevant information using multiple queries to cover different aspects.
        2. Save important findings as notes with clear topic labels.
        3. After gathering enough information, retrieve all your notes.
        4. Provide a well-structured summary of your research findings.

        Be thorough but concise. Cite your sources when possible.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics by searching the web and taking notes.",
    tools: tools);

// Get the research topic
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent              ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(" ", args);
}
else
{
    Console.Write("Enter a topic to research: ");
    topic = Console.ReadLine() ?? "artificial intelligence";
}

Console.WriteLine($"\nResearching: {topic}");
Console.WriteLine(new string('─', 40));

// Run the agent
var messages = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var session = await agent.CreateSessionAsync(cancellationToken: CancellationToken.None);
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
});

var response = await agent.RunAsync(messages, session, runOptions, CancellationToken.None);

Console.WriteLine("\n" + new string('═', 40));
Console.WriteLine("RESEARCH SUMMARY");
Console.WriteLine(new string('═', 40));

foreach (var message in response.Messages)
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine();

